using System;using System.IO;using System.Linq;using System.Text.Json;using System.Text.Json.Nodes;using System.Collections.Generic;using System.Reflection;using Sdt.Core;using Sdt.Core.Battle;
class Audit {
 sealed class Host:BattleHost { public int Hp{get;set;}=30;public int MaxHp=>60;public int Atk=>4;public int SpellPower=>2;public string MyClass=>null;public string CharacterId=>"wu";public IReadOnlyList<OwnedCard> OwnedCards{get;set;}=Array.Empty<OwnedCard>();public void Log(string text,string kind=null){}public void Heal(int n){Hp=Math.Min(MaxHp,Hp+n);}public void OnBattleEnd(BattleResult r){} }
 static RuleValue Rule(JsonObject data){var r=new RuleValue();foreach(var p in data)r.Values[p.Key]=Value(p.Value);return r;}
 static object Value(JsonNode v){if(v==null)return null;if(v is JsonObject o)return Rule(o);if(v is JsonArray a)return a.Select(Value).ToArray();var r=(JsonValue)v;if(r.TryGetValue<int>(out var n))return n;if(r.TryGetValue<bool>(out var b))return b;if(r.TryGetValue<string>(out var s))return s;return r.GetValue<double>();}
 static object Field(BattleSession b,string n)=>typeof(BattleSession).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(b);

 static object Snap(BattleSession b,Host h){var s=b.Snapshot;Func<IReadOnlyDictionary<string,int>,object> st=x=>x.Where(p=>p.Value!=0).OrderBy(p=>p.Key).ToDictionary(p=>p.Key,p=>p.Value);Func<IEnumerable<string>,object> zone=uids=>uids.Select(uid=>b.FindCard(uid)?.card).Where(c=>c!=null).Select(c=>new{id=c.id,cost=b.GetEffectiveCost(c),dmg=c.dmg??0}).OrderBy(c=>c.id,StringComparer.Ordinal).ToArray();return new{hp=h.Hp,energy=s.Energy,maxEnergy=(int)Field(b,"maxEnergy"),armor=s.Pdef.Armor,shield=s.Pdef.Shield,guard=s.Pdef.Guard,status=st(s.Pstat.Status),foes=s.Foes.Select(e=>new{hp=e.hp,atk=e.atk,dead=e.dead,status=st(e.status),armor=e.defense.Armor,shield=e.defense.Shield}).ToArray(),hand=zone(s.Hand),deck=zone(s.DrawPile),consumed=zone((List<string>)Field(b,"consumed"))};}
 static void Main(){CardLibrary.Init(()=>CardDatabase.All);var rows=JsonNode.Parse(File.ReadAllText("scan-source.json"))["rows"].AsArray();var result=new List<object>();foreach(var row in rows){var owned=row["input"].AsArray().Select(n=>{var c=n["card"].Deserialize<CardDef>(new JsonSerializerOptions{IncludeFields=true});c.rules=n["card"]["rules"] is JsonObject r?Rule(r):null;return new OwnedCard{uid=(string)n["uid"],card=c};}).ToArray();var host=new Host{OwnedCards=owned};var b=new BattleSession();b.Start(new BattleStartContext{host=host,rng=new Rng(123),enemies=new[]{new EnemyInput{id="foe",name="目标",hp=1000,atk=2}}});typeof(BattleSession).GetField("energy",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(b,10);typeof(BattleSession).GetField("maxEnergy",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(b,10);var card=owned[0].card;int side=BattleRules.TargetSideFor(card)=="self"?-1:0;var command=b.PlayCard("o0",side,false);var after=Snap(b,host);object turn=null;if(row["turn"]!=null){b.EndTurn();turn=Snap(b,host);}result.Add(new{id=(string)row["id"],ok=command.Ok,reason=command.Reason,after,turn});b.Retract();}File.WriteAllText("scan-core.json",JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(result.Count);}
}

